COMMAND_PAGE_SIZE = 32
COMMAND_PAGE_COUNT = (len(ALL_COMMANDS) + COMMAND_PAGE_SIZE - 1) // COMMAND_PAGE_SIZE

def command_page(page: int):
    page = max(1, min(int(page), COMMAND_PAGE_COUNT))
    start = (page - 1) * COMMAND_PAGE_SIZE
    return ALL_COMMANDS[start:start + COMMAND_PAGE_SIZE]
